import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testInitialSpeed() {
        val motor = Motor("Left")
        Assert.assertEquals("Left at 0.0", motor.getInfo())
    }

    @Test
    fun testRunAtSpeed() {
        val motor = Motor("Right")
        motor.runAt(0.75)
        Assert.assertEquals("Right at 0.75", motor.getInfo())
    }

    @Test
    fun testMultipleUpdates() {
        val motor = Motor("Arm")
        motor.runAt(0.5)
        motor.runAt(1.0)
        Assert.assertEquals("Arm at 1.0", motor.getInfo())
    }
}
